import java.util.*;
import java.io.*;

public class Main {
    static int n, m, P;
    static long[][] dwu;
    static long[] dp1;
    static long[][] dp2;
    static long[][] dp3;
    static long[] count_arr;

    static void multiply_self(long[] a, int b) {
        for (int i = 0; i < a.length; i++) {
            a[i] = (a[i] * b) % P;
        }
    }

    static long multiply(long a, long b) {
        return (a * b) % P;
    }

    static void add_mod(long[] a, long b) {
        for (int i = 0; i < a.length; i++) {
            a[i] = (a[i] + b) % P;
        }
    }

    static void add_mod(long[] a, long[] b) {
        for (int i = 0; i < a.length; i++) {
            a[i] = (a[i] + b[i]) % P;
        }
    }

    static void add_mod(long[] a, long b) {
        for (int i = 0; i < a.length; i++) {
            a[i] = (a[i] + b) % P;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        P = Integer.parseInt(st.nextToken());

        dwu = new long[n + 2][n + 2];
        for (int i = 0; i <= n + 1; i++) {
            for (int j = 0; j <= i; j++) {
                if (j == 0) {
                    dwu[i][j] = 1;
                } else {
                    dwu[i][j] = (dwu[i - 1][j] + dwu[i - 1][j - 1]) % P;
                }
            }
        }

        dp1 = new long[m + 2];
        count_arr = new long[m + 2];
        for (int i = 0; i <= m + 1; i++) {
            if (i == 0) {
                dp1[0] = 0;
                count_arr[0] = 1;
            }
        }

        for (int i = 1; i <= m; i++) {
            for (int j = 0; j < i; j++) {
                long val = 0;
                val = (val + multiply(dp1[j], count_arr[i - j - 1])) % P;
                val = (val + multiply(dp1[i - j - 1], count_arr[j])) % P;
                long tempVal = val;
                long jPlus1 = j + 1;
                long halfJPlus1 = jPlus1 * (jPlus1 - 1) / 2;
                val = (val * jPlus1) % P;
                long temp = (multiply(multiply(count_arr[i - j - 1], count_arr[j]), jPlus1)) % P;
                val = (val + temp) % P;
                multiply_self(new long[]{val}, (int) jPlus1);
                add_mod(dp1, new long[]{val});
                long temp2 = dwu[i - 1][j];
                temp2 = (temp2 * count_arr[j]) % P;
                temp2 = (temp2 * count_arr[i - j - 1]) % P;
                temp2 = (temp2 * jPlus1) % P;
                add_mod(count_arr, new long[]{temp2});
            }
            // Double the values
            for (int i2 = 0; i2 <= m; i2++) {
                dp1[i2] = (dp1[i2] * 2) % P;
                count_arr[i2] = (count_arr[i2] * 2) % P;
            }
        }

        int sizeN = n + 2;
        int sizeM = m + 2;
        dp2 = new long[sizeN][sizeM];
        dp3 = new long[sizeN][sizeM];

        dp2[0][0] = 1;

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                for (int k = 0; k <= m; k++) {
                    if (j + k <= m && i + k + 1 <= n + 1) {
                        long val = dp2[i][j];
                        val = (val * dwu[m - j][k]) % P;
                        val = (val * count_arr[k]) % P;
                        long val3 = dp3[i][j];
                        val3 = (val3 * count_arr[k]) % P;
                        val3 = (val3 + multiply(dp1[k], dp2[i][j])) % P;
                        val3 = (val3 * dwu[m - j][k]) % P;
                        int ni = i + k + 1;
                        int nj = j + k;
                        dp3[ni][nj] = (dp3[ni][nj] + val3) % P;
                        dp2[ni][nj] = (dp2[ni][nj] + val) % P;
                    }
                }
            }
        }

        System.out.println(dp3[n + 1][m]);
    }
}
